mapper.select:
SELECT t.* FROM agri_prod_trace_code t
WHERE t.deleted = 0 AND t.tenant_id = #{tenantId}

    AND t.trace_code LIKE CONCAT('%', #{dto.traceCode}, '%')


    AND t.batch_number = #{dto.batchNumber}


    AND t.product_name LIKE CONCAT('%', #{dto.productName}, '%')


    AND t.farm_code = #{dto.farmCode}


    AND t.status = #{dto.status}

ORDER BY t.create_time DESC
